<?php require '../../config/db.php';require '../../includes/functions.php';require '../../includes/auth.php';require_admin();if(!csrf_ok($_POST['csrf']??''))json_response(false,'Security token expired.',[],419);$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$caption=trim($_POST['caption']??'');if(strlen($title)<2||strlen($caption)<5)json_response(false,'Add a valid title and caption.',[],422);try{$img=upload_image($_FILES['image']??null,'gallery');$url=$img?:trim($_POST['image_url']??'');if(!$url)json_response(false,'Choose an image or provide an image URL.',[],422);if($id){$q=$pdo->prepare('UPDATE gallery SET title=?,caption=?,image_url=?,category=?,sort_order=?,status=? WHERE id=?');$q->execute([$title,$caption,$url,trim($_POST['category']??''),(int)($_POST['sort_order']??0),$_POST['status']??'published',$id]);}else{$q=$pdo->prepare('INSERT INTO gallery(title,caption,image_url,category,sort_order,status) VALUES(?,?,?,?,?,?)');$q->execute([$title,$caption,$url,trim($_POST['category']??''),(int)($_POST['sort_order']??0),$_POST['status']??'published']);}json_response(true,'Gallery saved successfully.');}catch(Throwable $e){json_response(false,'Could not save gallery.',[],422);}